INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('030c98ff-7d23-4774-811f-8079190b1820', '2d350c50-e999-4a4c-b8bf-eb151c5cbe33', 0, 'A digital signature — the document is hashed, and that hash is then encrypted with the signer''s PRIVATE key; anyone can verify the signature using the signer''s public key, which confirms both integrity (the hash matches) and non-repudiation (only the holder of that specific private key could have produced a signature verifiable with the matching public key) — a plain hash alone proves integrity but not who produced it.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fd50324e-6da9-4c03-a842-6135a5ee3804', '2d350c50-e999-4a4c-b8bf-eb151c5cbe33', 1, 'A plain SHA-256 hash of the document is sufficient on its own to prove both integrity and non-repudiation, with no additional cryptographic step needed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f920f68-c8a5-4066-9315-437ef6c28a5d', '2d350c50-e999-4a4c-b8bf-eb151c5cbe33', 2, 'Symmetric encryption of the document using a key shared between the executive and the recipient provides non-repudiation, since only they two possess the shared key.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f00390a-6049-41c0-8e90-455df17c8dfa', '2d350c50-e999-4a4c-b8bf-eb151c5cbe33', 3, 'Non-repudiation is not achievable through any cryptographic mechanism and requires only a physical witness.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0a1163e-d12f-4e03-b5cc-964f5e45fe7e', '12be1187-cdcb-4f47-9b4b-3e0cbb4c4bfa', 0, 'The AAA framework — Authentication (verifying who you are), Authorization (determining what you''re allowed to do), and Accounting (logging what you actually did) — three genuinely distinct functions often confused with each other despite frequently working together in the same system.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('239ecf46-17bb-4048-8649-488378de8bb3', '12be1187-cdcb-4f47-9b4b-3e0cbb4c4bfa', 1, 'Authentication, Authorization, and Accounting are fully interchangeable terms describing the exact same single function.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('634eef2a-f9e6-40ac-a12e-ae23849f47d8', '12be1187-cdcb-4f47-9b4b-3e0cbb4c4bfa', 2, 'This framework is called CIA, the same as the CIA confidentiality/integrity/availability triad, with no distinction between the two concepts.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1bb70a3-7e1b-4de1-b32b-8cd6954bc06a', '12be1187-cdcb-4f47-9b4b-3e0cbb4c4bfa', 3, 'Only Authentication is a real security concept; Authorization and Accounting are not recognized security functions.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0c6d341-5897-4a85-8eb3-7ccf1ee245f6', '270e41f7-4ec8-4ca8-a250-b15a7482ef9c', 0, 'Business Email Compromise (BEC) — a targeted social engineering attack, often impersonating a known vendor, executive, or partner, specifically designed to manipulate an employee into making a fraudulent payment or divulging sensitive financial information, typically without any malware involved at all.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('840afee8-78ec-4c0e-85f9-b34d0948dacc', '270e41f7-4ec8-4ca8-a250-b15a7482ef9c', 1, 'A worm, since worms are defined as any email-based fraud scheme.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ccd123bb-4471-4615-863e-c1f8f9ffcddb', '270e41f7-4ec8-4ca8-a250-b15a7482ef9c', 2, 'A rootkit, since rootkits are responsible for impersonating vendor payment details in email.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0dcb337b-b2ef-481a-85d7-732a010fe56a', '270e41f7-4ec8-4ca8-a250-b15a7482ef9c', 3, 'A buffer overflow, since buffer overflows are the mechanism behind fraudulent wire transfer requests.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0fb6c7c5-8e1d-440a-8ca0-ae4ec959bf4a', '84fbe85f-7e3f-473e-b720-3c76672640c0', 0, 'Cross-Site Request Forgery (CSRF) — tricks the victim''s browser into submitting an unwanted, authenticated request using their existing session, exploiting the trust a site has in the victim''s browser; this differs from XSS, which instead injects and executes malicious SCRIPT CODE that runs within the context of a vulnerable site to steal data or perform actions directly, a different mechanism.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67590678-a4e8-47b7-8245-460c6f0cf3af', '84fbe85f-7e3f-473e-b720-3c76672640c0', 1, 'CSRF and XSS are fully identical vulnerabilities with no meaningful technical distinction between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f24c1593-1805-4944-9a42-88a34d470ed2', '84fbe85f-7e3f-473e-b720-3c76672640c0', 2, 'This is SQL injection, since any web-based attack exploiting a logged-in user''s session is classified as SQL injection.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('181d94d2-086d-473e-b0e9-4158270bb108', '84fbe85f-7e3f-473e-b720-3c76672640c0', 3, 'This scenario describes a physical security vulnerability, unrelated to web application security.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4829a24b-5cc0-4c9a-acd7-d16f49042f13', 'a04050ac-3786-46c1-a9f5-cb8cc40476a2', 0, 'A zero-day vulnerability — by definition, no patch exists yet at the time it''s being actively exploited (the vendor has had "zero days" to fix it since first learning of it, or in some cases hasn''t even learned of it yet), so routine patching (which relies on a patch already existing to apply) offers no protection until a patch is eventually released; other layered defenses (behavioral detection like EDR, network segmentation, least privilege) are needed to reduce exposure in the meantime.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd1bf9b6-1418-47fb-9d3b-f9645a32c5f0', 'a04050ac-3786-46c1-a9f5-cb8cc40476a2', 1, 'A known vulnerability, since "zero-day" simply means the vulnerability has existed for zero days total, regardless of patch availability.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('457aad92-bff2-4a7d-b473-919e0dc17b95', 'a04050ac-3786-46c1-a9f5-cb8cc40476a2', 2, 'Patch management always protects fully against zero-day vulnerabilities, since patches are released simultaneously with vulnerability discovery in every case.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0f9e1b1-bc1d-44f5-bab2-435ee2f90e8e', 'a04050ac-3786-46c1-a9f5-cb8cc40476a2', 3, 'Zero-day vulnerabilities only affect hardware, never software.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('513eaf59-8bc0-48bb-8289-c1924e03254e', 'f76952e0-1bb3-4e07-a6d5-2878a3042661', 0, 'An evil twin (or rogue access point) attack — a malicious wireless access point impersonating a legitimate one (often with a matching SSID and a stronger signal to preferentially attract connections), allowing the attacker to intercept, monitor, or manipulate all traffic from victims who unknowingly connect to it instead of the real network.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('978361b3-b7ea-4515-a810-91be1373e27c', 'f76952e0-1bb3-4e07-a6d5-2878a3042661', 1, 'A worm, since worms are defined as any attack involving a wireless access point.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c72a24e-244c-4b4f-90c9-280b5bdce884', 'f76952e0-1bb3-4e07-a6d5-2878a3042661', 2, 'A buffer overflow, since buffer overflows are the mechanism used to impersonate a Wi-Fi network name.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7bfea020-82c3-4568-a9b3-2ce34cad12ff', 'f76952e0-1bb3-4e07-a6d5-2878a3042661', 3, 'This scenario describes a physically impossible attack, since two access points can never share the same network name.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('44cd721b-6c88-4a21-bf80-c59b78c70ff3', '96fbb305-8b01-487f-bcfb-e39f1b8088a1', 0, 'An air-gapped network — the system has NO physical network connection whatsoever to the internet or any other network segment, making remote compromise via network-based attack technically impossible (though it does not eliminate other vectors, like a compromised removable USB drive being physically connected).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('948d7b97-fbcf-4521-ae0a-6af4c76ba80a', '96fbb305-8b01-487f-bcfb-e39f1b8088a1', 1, 'A well-configured firewall alone, since a sufficiently strict firewall rule set provides the exact same absolute guarantee as having no physical network connection at all.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b20282b-ef03-4fee-ac9e-8ddca8a42bf3', '96fbb305-8b01-487f-bcfb-e39f1b8088a1', 2, 'A VPN, since VPNs by definition make a system completely unreachable from any other network.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9f8e1ee6-631b-4418-a638-619219a53ab0', '96fbb305-8b01-487f-bcfb-e39f1b8088a1', 3, 'This guarantee is not achievable through any network architecture approach.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b81a94ee-e71d-478f-a323-b0447c10d0b0', 'dc07967e-3656-47ee-a126-365f96dc7c39', 0, 'Containerization (e.g., Docker-style containers), which isolates each workload''s filesystem, processes, and (with proper configuration) network namespace from others on the same host, providing meaningfully more isolation than running processes side-by-side with no isolation, while sharing the host OS kernel and thus being more lightweight than a full VM with its own complete OS.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d56d5533-c15d-46b3-976d-71a3d8319aa8', 'dc07967e-3656-47ee-a126-365f96dc7c39', 1, 'Running all workloads as regular, unisolated processes directly on the host OS, since this provides identical isolation to containerization with no meaningful difference.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('43280854-97cd-4b98-86fe-98cae29a3cab', 'dc07967e-3656-47ee-a126-365f96dc7c39', 2, 'A VPN, since VPNs provide process-level isolation between workloads running on the same physical host.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2529c29-6596-4cab-92ba-de447d4ee21a', 'dc07967e-3656-47ee-a126-365f96dc7c39', 3, 'No technology exists that provides isolation lighter-weight than a full virtual machine.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62e5ef28-7a58-448d-b843-04fc3c109362', '15876a35-0a75-4c22-b996-e793e00c44b6', 0, 'In a public cloud, security responsibility is SHARED between the cloud provider (securing the underlying infrastructure) and the customer (securing their own data, access configuration, and applications built on top) — a "shared responsibility model"; in a private cloud (owned/operated entirely by the organization itself), the organization bears the FULL security responsibility for every layer, since there is no external provider to share it with; a hybrid approach combines both models across its respective public and private portions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dfa08c7e-08d0-4f05-9a94-b9d00f543bbb', '15876a35-0a75-4c22-b996-e793e00c44b6', 1, 'Public cloud providers bear 100% of all security responsibility for every layer including the customer''s own application code and data, with zero responsibility remaining on the customer in any configuration.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cefd134d-20f7-451e-b407-cbb808efdfb8', '15876a35-0a75-4c22-b996-e793e00c44b6', 2, 'Private cloud deployments always have LESS security responsibility for the organization than public cloud, since a private cloud has no external attack surface of any kind.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4192cfef-f8ea-4ec6-8532-f3e62a9073b2', '15876a35-0a75-4c22-b996-e793e00c44b6', 3, 'Security responsibility is identical and undifferentiated across public, private, and hybrid cloud models, with no meaningful distinction between them.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d265cdb0-b9de-485a-8972-db5cfc5e316d', '7b2050da-a4e8-4202-9c10-40ea09176b43', 0, 'A bastion host (or jump box/jump server) — a single, deliberately hardened and closely monitored server acting as the sole controlled entry point into a private network segment, reducing the attack surface to one carefully secured system instead of exposing every individual private server directly.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5e6db23-7cb4-4574-b3c0-01305eb8be5a', '7b2050da-a4e8-4202-9c10-40ea09176b43', 1, 'A honeynet, since honeynets are the standard mechanism for legitimate administrative access to private servers.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1484c953-68ed-4b87-9336-289b724a02c7', '7b2050da-a4e8-4202-9c10-40ea09176b43', 2, 'A DLP appliance, since DLP''s primary function is providing administrative network access to private subnets.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09210917-d70f-4520-8cc6-9f2d733eda4f', '7b2050da-a4e8-4202-9c10-40ea09176b43', 3, 'This architecture pattern provides no security benefit over exposing every private server directly to the internet.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7232477-7e9e-48bb-9dc5-11e8e874fb73', '4e248a5b-2e64-4513-a10d-160f7e3930ca', 0, 'Centralized log management/aggregation — forwarding logs from every system to a central log repository (often the same pipeline feeding a SIEM) with a consistently enforced retention policy, so logs are preserved for the required duration regardless of any individual system''s local, inconsistent default retention settings.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9efbe6b9-e62b-4f89-a2df-3d766df33561', '4e248a5b-2e64-4513-a10d-160f7e3930ca', 1, 'Nothing needs to change, since every system''s local default log retention setting is always sufficient for any investigation need.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a444f591-7a5e-4be2-a147-039c492112a8', '4e248a5b-2e64-4513-a10d-160f7e3930ca', 2, 'Disabling logging entirely on all systems, since fewer logs reduce the risk of a future investigation being needed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d851d13-de8b-4683-a840-acffd31d76d6', '4e248a5b-2e64-4513-a10d-160f7e3930ca', 3, 'Log retention periods can never be centrally configured or enforced across multiple systems under any circumstance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5fa880ae-f6a7-4cf6-8afe-0188622c750b', '334bd578-6b7f-43d7-a2ef-74909580d97d', 0, 'The vulnerability management lifecycle — after identification (the scan itself), findings are PRIORITIZED based on factors like severity/CVSS score, whether the vulnerability is being actively exploited in the wild, and the criticality/exposure of the affected asset (an internet-facing system with a critical vulnerability outranks an internal, low-exposure system with the same CVSS score) — then remediated in that prioritized order, and finally VERIFIED as actually fixed, not just marked complete.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c05dc783-bb5b-4d35-bc02-348e90b66016', '334bd578-6b7f-43d7-a2ef-74909580d97d', 1, 'All 200 findings should always be fixed in the exact numerical order the scanning tool happened to list them, regardless of severity or exposure.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf04062d-d9bc-450f-a9e3-92110e933f20', '334bd578-6b7f-43d7-a2ef-74909580d97d', 2, 'Vulnerability prioritization is unnecessary, since every finding from a scan carries identical real-world risk by definition.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c32ed29b-3940-48c0-904d-b034288f7178', '334bd578-6b7f-43d7-a2ef-74909580d97d', 3, 'Remediation should be assigned entirely at random with no structured criteria of any kind.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7909f8f8-e3f3-4119-8c30-f4e36cc20dde', '9e7802fd-c5e2-4731-9905-179a507f0df2', 0, 'Threat intelligence, specifically in the form of Indicators of Compromise (IOCs) — externally sourced, continuously updated data about known-malicious infrastructure/artifacts that an organization can match against its own environment to detect activity associated with known threats, often faster than internally discovering the same threat from scratch.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1fcf122b-561b-4ee7-9a80-cc63b8f30b77', '9e7802fd-c5e2-4731-9905-179a507f0df2', 1, 'Digital forensics, since collecting external malicious-IP feeds is the definition of digital forensics.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7f1918a-12a1-4500-a45c-ec3a4f806f0e', '9e7802fd-c5e2-4731-9905-179a507f0df2', 2, 'A Business Impact Analysis, since BIAs are built by subscribing to external malicious-IP and malware-hash feeds.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84e6e23c-365c-4473-997d-fc3207d42891', '9e7802fd-c5e2-4731-9905-179a507f0df2', 3, 'This practice provides no security value, since malicious IPs and hashes change too quickly for any feed to ever be useful.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('037f8fc1-4319-46b1-8767-690e82b1253b', 'bb3c9863-825c-4300-899c-ab9ec6ed6f5f', 0, 'Privileged Access Management (PAM), which provides just-in-time, time-limited elevation of privileged access (rather than standing/always-on admin rights), typically with request/approval workflows and automatic revocation when the granted window expires, directly reducing the standing attack surface a permanently-privileged account represents.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81daaa35-ac5f-4186-adfd-762c88229ffa', 'bb3c9863-825c-4300-899c-ab9ec6ed6f5f', 1, 'Granting the administrator permanent, standing admin privileges at all times is the recommended approach, since time-limiting access provides no security benefit.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('536369e0-141f-453f-9232-6d49fb4e3b13', 'bb3c9863-825c-4300-899c-ab9ec6ed6f5f', 2, 'A VPN, since VPNs are specifically designed to provide time-limited, automatically-revoked elevated database privileges.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a527330-8814-49d7-9768-af24857d96ff', 'bb3c9863-825c-4300-899c-ab9ec6ed6f5f', 3, 'This kind of time-limited privilege elevation is not achievable through any security technology or practice.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('345d6e3c-d2d5-4e35-9f29-c384e4f18707', 'cda98e8d-1932-4035-8a2c-eebb21bc5baa', 0, 'Data Loss Prevention (DLP), which inspects content in motion (like outbound email), at rest, or in use for patterns matching sensitive data types (credit card numbers, SSNs, specific classified-data markers), and can automatically block, quarantine, or alert on a match before the data actually leaves the organization''s control.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b140e97-e018-4279-8649-89d0e042a17a', 'cda98e8d-1932-4035-8a2c-eebb21bc5baa', 1, 'A firewall alone, since firewalls inspect outbound email content for embedded credit card numbers by default.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec087cfb-83da-4858-ba33-9c4bfbfb8479', 'cda98e8d-1932-4035-8a2c-eebb21bc5baa', 2, 'AWS KMS, since KMS''s core function is scanning email content for sensitive data patterns.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0425666e-1716-4363-a491-3f6f688c2970', 'cda98e8d-1932-4035-8a2c-eebb21bc5baa', 3, 'This kind of content-aware outbound data blocking is not achievable through any security technology.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9408113-5b31-410e-9c5b-df19f4ed18be', '3837b3b1-6fb6-41c7-b492-a6d12b9becbb', 0, 'Availability (from the CIA triad) and Continuity of Operations — physical power redundancy is a concrete, foundational example of ensuring systems remain AVAILABLE through a real disruption, directly supporting broader business continuity, even though a generator/UPS is a physical infrastructure control, not a purely digital/network one.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('49f5d4f1-cf5e-4058-a6e3-4d929509b03a', '3837b3b1-6fb6-41c7-b492-a6d12b9becbb', 1, 'Confidentiality (from the CIA triad), since power redundancy is specifically designed to keep data secret from unauthorized readers.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4798b995-9d9e-42b5-b374-82d2866f72eb', '3837b3b1-6fb6-41c7-b492-a6d12b9becbb', 2, 'Non-repudiation, since a UPS and generator are what allow a user to be held accountable for their actions during a power outage.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c7e8f9e-2d8f-40d9-9cb1-a6304ff9db6a', '3837b3b1-6fb6-41c7-b492-a6d12b9becbb', 3, 'Physical power infrastructure has no relationship to any recognized security concept.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5313c5b1-78ba-475e-ade2-cc1063195077', '25a4a6ec-89d0-462c-b66d-fafc60fb12c1', 0, 'Third-party/vendor risk management — assessing the vendor''s own security posture (e.g., reviewing their compliance certifications/audit reports, covered in Paper 2) before granting access to sensitive data, and establishing contractual security requirements and ongoing monitoring, since the vendor''s security weaknesses become a real risk to the company''s own data once that data is shared.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d56abd0d-c197-47c3-8a8b-3a7cba715a38', '25a4a6ec-89d0-462c-b66d-fafc60fb12c1', 1, 'No due diligence is necessary, since a vendor''s own security posture has no bearing on risk to data the company shares with them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46f0bc11-2932-4a54-85a4-f05647d5bb7f', '25a4a6ec-89d0-462c-b66d-fafc60fb12c1', 2, 'The company''s own security controls become entirely irrelevant once any data is shared with a third party, making any assessment pointless.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af6093ef-93cf-478d-b7f9-775913a26cca', '25a4a6ec-89d0-462c-b66d-fafc60fb12c1', 3, 'Vendor risk only needs to be assessed AFTER a breach has already occurred at that vendor, never proactively beforehand.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4efcb516-5b07-47f9-bfa7-ee491fce5c18', 'daa8e1b8-dc8c-4818-9465-55a5a54a2f21', 0, 'Change management — a formal process requiring proposed changes to production systems to be documented, reviewed (often by a change advisory board or peer review), and approved before implementation, specifically to catch unintended consequences (like an inadvertently opened port) before they reach production, rather than discovering them after the fact.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1d4b4c2-18f1-4d88-a02e-ade9d4798184', 'daa8e1b8-dc8c-4818-9465-55a5a54a2f21', 1, 'Change management is unnecessary overhead, since any administrator with valid credentials should always be free to modify production systems directly with no review of any kind.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a5ae541-831b-4664-80a9-904987fa8cf5', 'daa8e1b8-dc8c-4818-9465-55a5a54a2f21', 2, 'This risk can only be caught by digital forensics after an incident has already occurred, never proactively beforehand.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de6cb00d-6061-4eb2-a8c6-cbb5708640b5', 'daa8e1b8-dc8c-4818-9465-55a5a54a2f21', 3, 'Change management applies only to application code changes, never to infrastructure configuration like firewall rules.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('011873cc-6a2d-42ce-ac70-aa906879d1a3', '3f1df87c-fc89-449e-a227-04d473998896', 0, 'A legal hold (or litigation hold) — a legal obligation to suspend normal data destruction/retention schedules and preserve all data potentially relevant to pending or reasonably anticipated litigation, which overrides the organization''s normal retention policy for the affected data until the hold is lifted.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c4fa49b2-a299-437c-8a7d-6b941721bec7', '3f1df87c-fc89-449e-a227-04d473998896', 1, 'A Business Impact Analysis, since BIAs are the mechanism that legally suspends normal data deletion during litigation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b010b100-bb06-47ce-96cf-346f596e00bf', '3f1df87c-fc89-449e-a227-04d473998896', 2, 'The company''s normal 90-day retention policy always takes precedence over any pending litigation, with no exception ever required.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4db01577-7e3d-4dd0-acfe-cde4934cfe54', '3f1df87c-fc89-449e-a227-04d473998896', 3, 'This concept does not exist; data retention policies are never affected by legal proceedings.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad92e890-9a0b-47a1-9084-804a08613e3a', 'a1f74a98-fb86-4e42-b762-e8fe49d0e67d', 0, 'Separation of duties — splitting a sensitive process into multiple steps requiring DIFFERENT people, specifically so no single individual can complete the entire sensitive action alone (reducing both fraud risk and the impact of one person''s error); this differs from least privilege (covered in Paper 1), which limits how much access any ONE individual has, but does not by itself prevent that one sufficiently-privileged individual from completing an entire sensitive process alone.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df80bb8d-6368-4c58-888a-829f7191043e', 'a1f74a98-fb86-4e42-b762-e8fe49d0e67d', 1, 'Separation of duties and least privilege are fully identical concepts describing the exact same control with no meaningful distinction.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35e641c7-7f84-4d0e-a25d-0cd64328fc33', 'a1f74a98-fb86-4e42-b762-e8fe49d0e67d', 2, 'This is called non-repudiation, since requiring two different approvers is the definition of non-repudiation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21f0c1f3-11a1-4b2d-b61b-316426a7a2b0', 'a1f74a98-fb86-4e42-b762-e8fe49d0e67d', 3, 'Requiring two different people for a sensitive action provides no real fraud-prevention benefit over a single authorized person.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
